CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT','PUBLISHED');
CREATE TABLE "Project" ("id" UUID NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"category" TEXT NOT NULL,"shortDescription" TEXT NOT NULL,"description" TEXT NOT NULL,"coverImage" TEXT NOT NULL DEFAULT '',"images" TEXT[] NOT NULL,"technologies" TEXT[] NOT NULL,"githubUrl" TEXT NOT NULL DEFAULT '',"liveUrl" TEXT NOT NULL DEFAULT '',"featured" BOOLEAN NOT NULL DEFAULT false,"status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT',"role" TEXT NOT NULL DEFAULT '',"features" TEXT[] NOT NULL,"benefits" TEXT[] NOT NULL,"accent" TEXT NOT NULL DEFAULT 'cyan',"preview" TEXT NOT NULL DEFAULT 'generic',"sortOrder" INTEGER NOT NULL DEFAULT 100,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Project_slug_key" ON "Project"("slug");
CREATE INDEX "Project_status_featured_sortOrder_idx" ON "Project"("status","featured","sortOrder");
